// 这里的 script 标签用来定义组件的逻辑部分，包括数据、方法等。我们使用了 Vue 3 的 Composition API 来定义组件的 setup 函数
//是用来写js的

import $ from 'jquery'; // 引入 jQuery 库
import { ref } from 'vue'; // 引入 ref 函数，用于创建响应式数据

export default {
  name: 'App',
  // 对象的名称
  setup: () => {
    let bot_name = ref(""); // 创建一个响应式变量 bot_name
    let bot_rating = ref(""); // 创建一个响应式变量 bot_rating

    $.ajax({
      // 使用 jQuery 的 ajax 方法请求后端数据
      url: "http://127.0.0.1:3000/pk/getbotinfo/",
      type: "get",
      // 请求类型为 GET
      success: resp => {
        bot_name.value = resp.name; // 将响应中的 bot_name 赋值给 bot_name 变量
        bot_rating.value = resp.rating; // 将响应中的 bot_rating 赋值给 bot_rating 变量
      }
    });
    return {
      bot_name,
      bot_rating
    };
  }
};
